def predict_output(grid):
    out = [[grid[r][c] for c in range(w)] for r in range(h)]

    # Find original 2 position
    orig_2_pos = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                orig_2_pos = (r, c)
                break
    if orig_2_pos:
        print(f"Original 2 at {orig_2_pos}")

    # Find gap columns (columns with 0 in rows containing 8)
    gap_cols = {}  # col -> list of row numbers where gap occurs
    for r in range(h):
        row_has_8 = any(grid[r][c] == 8 for c in range(w))
        row_has_0 = any(grid[r][c] == 0 for c in range(w))
        if row_has_8 and row_has_0:
            for c in range(w):
                if grid[r][c] == 0:
                    if c not in gap_cols:
                        gap_cols[c] = []
                    gap_cols[c].append(r)

    print(f"Gap columns: {sorted(gap_cols.keys())}")

    # Fill in 2s based on gap columns and rows
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:  # Only fill zeros
                # Check if this zero is between two gap occurrences or connected to a gap
                # Going up
                up_gaps = [g for g in gap_cols.get(c, []) if g < r]
                # Going down
                down_gaps = [g for g in gap_cols.get(c, []) if g > r]

                if up_gaps:
                    # Has a gap above, so potentially fill upwards from nearest gap
                    nearest_up = max(up_gaps)
                    # Check if path is clear (no other 8s between)
                    path_clear = True
                    for rr in range(nearest_up + 1, r):
                        if grid[rr][c] != 0:
                            path_clear = False
                            break

                    if path_clear:
                        out[r][c] = 2

                elif down_gaps:
                    # Has a gap below, so potentially fill downwards towards it
                    nearest_down = min(down_gaps)
                    # Check if path is clear
                    path_clear = True
                    for rr in range(r + 1, nearest_down):
                        if grid[rr][c] != 0:
                            path_clear = False
                            break

                    if path_clear:
                        out[r][c] = 2

    return out

