def predict_row_range(row_idx, grid, gap_rows, orig_2_cols=None):
    """Predict which columns should have 2s for an empty row"""
    h, w = len(grid), len(grid[0])

    # Find nearest 8-rows
    closest_above = None
    closest_below = None

    for a_r in range(row_idx - 1, max(-1, row_idx - 6), -1):
        if a_r >= 0 and any(grid[a_r][c] == 8 for c in range(w)):
            closest_above = a_r
            break

    for b_r in range(row_idx + 1, min(h, row_idx + 6)):
        if any(grid[b_r][c] == 8 for c in range(w)):
            closest_below = b_r
            break

    # Collect all gap columns from nearby gap-rows
    if orig_2_cols is None:
        orig_2_cols = set(c for r in range(h) for c in range(w) if grid[r][c] == 2)

    cols_to_consider = set(orig_2_cols)
    if closest_above in gap_rows:
        cols_to_consider.update(gap_rows[closest_above])
    if closest_below in gap_rows:
        cols_to_consider.update(gap_rows[closest_below])

    # If only ONE gap-neighbor exists, use just those columns
    num_gap_neighbors = sum(1 for gap_r in [closest_above, closest_below] 
                           if gap_r is not None and gap_r in gap_rows)

    print(f"  Gap neighbors: above={closest_above}, below={closest_below}")
    print(f"  All gap cols collected: {sorted(cols_to_consider)}")

    if num_gap_neighbors == 0:
        return sorted(cols_to_consider)  # Just original 2s

    if num_gap_neighbors == 1:
        # Use just the gap from the single neighbor
        single_neighbor = closest_above if closest_above else closest_below
        if single_neighbor in gap_rows:
            return sorted(gap_rows[single_neighbor])

    # Two or more neighbors: take MIN/MAX
    if cols_to_consider:
        return list(range(min(cols_to_consider), max(cols_to_consider) + 1))
    return []

