    if cols_to_consider:
        return list(range(min(cols_to_consider), max(cols_to_consider) + 1))
    return []

# Now determine if a row should be FULL (all columns become 2)
def should_be_full_row(row_idx, grid, gap_rows, orig_2_cols):
    """Check if this empty row should be completely filled with 2s"""
    h, w = len(grid), len(grid[0])

    # Find nearest 8-rows
    closest_above = None
    closest_below = None

    for a_r in range(row_idx - 1, max(-1, row_idx - 6), -1):
        if a_r >= 0 and any(grid[a_r][c] == 8 for c in range(w)):
            closest_above = a_r
            break

    for b_r in range(row_idx + 1, min(h, row_idx + 6)):
        if any(grid[b_r][c] == 8 for c in range(w)):
            closest_below = b_r
            break

    # Full row condition: closest 8-rows are separated by EXACTLY 2 rows (the current one being middle)
    if closest_above is not None and closest_below is not None:
        dist_above = row_idx - closest_above - 1  # rows between them above
        dist_below = closest_below - row_idx - 1   # rows between them below

        # If we're the SINGLE middle row between two 8-rows
        if dist_above == 1 and dist_below == 1:
            # Check if combined 8 count exceeds threshold
            cnt_above = sum(1 for x in grid[closest_above] if x == 8)
            cnt_below = sum(1 for x in grid[closest_below] if x == 8)
            total = cnt_above + cnt_below

            print(f"    FULL ROW CHECK: above={closest_above}({cnt_above}), below={closest_below}({cnt_below}), total={total}")

            # If total 8s > 30, make it full
            if total > 30:
                return True

    return False

