def dist_to_gap_row(row_idx):
    """Returns (dist, gap_row) where dist=0 means adjacent, or None"""
    # Find all gap-rows and their distances
    candidates = []
    for g_r in gap_rows:
        if g_r > row_idx:
            dist = g_r - row_idx - 1  # -1 because we don't count the target row itself
            candidates.append((dist, g_r))
        elif g_r < row_idx:
            dist = row_idx - g_r - 1
            candidates.append((dist, g_r))

    if not candidates:
        return None

    closest = min(candidates, key=lambda x: x[0])
    return closest

