orig_2_cols = set(c for r in range(h) for c in range(w) if demo_in[r][c] == 2)

def predict_range(row_idx):
    """Predict 2-range for empty row"""
    # Find all nearby gap-rows (within 6 rows)
    nearby_gaps = []
    for g_r in gap_rows:
        dist = abs(g_r - row_idx)  # Direct adjacency check
        if dist <= 6:
            nearby_gaps.append((dist, g_r, gap_rows[g_r]))

    nearby_gaps.sort(key=lambda x: x[0])

    if not nearby_gaps:
        return list(orig_2_cols)

    # Check adjacency status
    has_adj_gap_above = any(dist == 1 and g_r < row_idx for dist, g_r, _ in nearby_gaps)
    has_adj_gap_below = any(dist == 1 and g_r > row_idx for dist, g_r, _ in nearby_gaps)
    has_non_adj_gap = any(dist > 1 for dist, _, _ in nearby_gaps)

    print(f"row={row_idx}")
    print(f"  nearby_gaps: {nearby_gaps[:3]}")
    print(f"  has_adj_gap_above={has_adj_gap_above}, has_adj_gap_below={has_adj_gap_below}, has_non_adj_gap={has_non_adj_gap}")
    print(f"  orig_2_cols={sorted(orig_2_cols)}")

    # Rule 1: No nearby gaps -> just original 2s
    if not nearby_gaps:
        return list(orig_2_cols)

    # Rule 2: Non-adjacent to nearest gap -> keep exactly one value
    # (original 2 position or the single closest gap column)
    if not has_adj_gap_above and not has_adj_gap_below:
        # Return only the single closest gap column(s)
        closest_gap = min(nearby_gaps, key=lambda x: x[0])[2]
        return closest_gap

    # Rule 3: Adjacent to ONE gap row only -> take those exact gaps (expanded by orig_2 if present)
    num_adj = sum(1 for dist, _, _ in nearby_gaps if dist == 1)
    if num_adj == 1:
        single_gap_row = next(g_r for dist, g_r, _ in nearby_gaps if dist == 1)
        single_gaps = gap_rows[single_gap_row]
        # If orig_2 is within this gap range, use the expanded range; otherwise just the gaps
        if orig_2_cols and any(min(single_gaps) <= c <= max(single_gaps) for c in orig_2_cols):
            return list(range(min(single_gaps), max(single_gaps) + 1))
        return single_gaps

    # Rule 4: Adjacent to BOTH above AND below gap-rows -> expand to union of all nearby gaps
    if has_adj_gap_above and has_adj_gap_below:
        cols = set()
        for dist, g_r, gaps in nearby_gaps:
            cols.update(gaps)
        return list(range(min(cols), max(cols) + 1))

    # Fallback
    all_cols = set()
    for dist, g_r, gaps in nearby_gaps:
        all_cols.update(gaps)
    return sorted(all_cols)

