gap_rows_demo = {}
for r in range(h_demo):
    if 8 in demo_in[r] and 0 in demo_in[r]:
        gap_rows_demo[r] = sorted([c for c in range(w_demo) if demo_in[r][c] == 0])

orig_2_cols_demo = set(c for r in range(h_demo) for c in range(w_demo) if demo_in[r][c] == 2)

def predict_range(row_idx, gap_rows, orig_2_cols):
    """Predict 2-range for empty row"""
    nearby_gaps = []
    for g_r in gap_rows:
        dist = abs(g_r - row_idx)
        if dist <= 6:
            nearby_gaps.append((dist, g_r, gap_rows[g_r]))

    nearby_gaps.sort(key=lambda x: x[0])

    if not nearby_gaps:
        return list(orig_2_cols)

    adj_grs_above = [gr for d, gr, _ in nearby_gaps if d == 1 and gr < row_idx]
    adj_grs_below = [gr for d, gr, _ in nearby_gaps if d == 1 and gr > row_idx]
    other_grs_above = [gr for d, gr, _ in nearby_gaps if d > 1 and gr < row_idx]
    other_grs_below = [gr for d, gr, _ in nearby_gaps if d > 1 and gr > row_idx]

    has_gaps_above = bool(adj_grs_above or other_grs_above)
    has_gaps_below = bool(adj_grs_below or other_grs_below)

    # Rule 1: Sandwiched (adjacent on BOTH sides) -> expand/union
    if adj_grs_above and adj_grs_below:
        cols = set()
        for d, gr, g in nearby_gaps:
            cols.update(g)

        min_col = min(cols)
        max_col = max(cols)
        width = max_col - min_col + 1

        if orig_2_cols and any(min_col <= c <= max_col for c in orig_2_cols):
            if width >= w_demo * 0.7:
                return list(range(0, w_demo))
            return list(range(min_col, max_col + 1))
        return sorted(cols)

    # Rule 2: Single adjacency with orig_2 INSIDE gap range -> expanded range
    if len(adj_grs_above) + len(adj_grs_below) == 1:
        single_gr = adj_grs_above[0] if adj_grs_above else adj_grs_below[0]
        single_gaps = gap_rows[single_gr]
        min_g, max_g = min(single_gaps), max(single_gaps)

        if any(min_g <= c <= max_g for c in orig_2_cols):
            # Include gap range AND orig_2 (convert orig_2 to set first)
            all_cols = set(list(range(min_g, max_g + 1))) | orig_2_cols
            return sorted(all_cols)
        return single_gaps

    # Rule 3: No adjacency and gaps ONLY on one side -> use orig_2_cols
    if not adj_grs_above and not adj_grs_below:
        if not has_gaps_above or not has_gaps_below:
            return list(orig_2_cols)

    # Rule 4: No adjacency but gaps on BOTH sides -> use nearest gap
    if not adj_grs_above and not adj_grs_below:
        closest_gap = min(nearby_gaps, key=lambda x: x[0])
        return closest_gap[2]

    # Fallback
    return list(orig_2_cols)

